function loaded = unified_reload_candidate_dependencies()
%UNIFIED_RELOAD_CANDIDATE_DEPENDENCIES Evaluator-side selective reload.
% Candidates without a dependency manifest require no reload. Public inputs
% are assigned by the task evaluator afterward.

manifestPath = string(getenv( ...
    "SIMUVERITY_CANDIDATE_DEPENDENCY_MANIFEST"));
submissionRoot = string(getenv( ...
    "SIMUVERITY_RUNTIME_SUBMISSION_BUNDLE"));
publicNamesJson = string(getenv( ...
    "SIMUVERITY_CANDIDATE_DEPENDENCY_PUBLIC_INPUT_NAMES_JSON"));
if strlength(manifestPath) == 0
    loaded = struct( ...
        "schema", "simuverity.candidate-dependency-load.v1", ...
        "status", "NO_DEPENDENCY_PACKAGE", ...
        "loaded_workspace_variables", strings(0, 1), ...
        "public_inputs_loaded", false);
    return;
end
assert(isfile(manifestPath) && isfolder(submissionRoot), ...
    "SimuVerity:CandidateClosure:EvaluatorBindingMissing", ...
    "The dependency manifest or runtime submission is missing.");
if strlength(publicNamesJson) == 0
    publicNames = strings(0, 1);
else
    decoded = jsondecode(publicNamesJson);
    publicNames = string(decoded(:));
end
loaded = unified_load_candidate_dependencies( ...
    manifestPath, submissionRoot, publicNames);
loaded.status = "LOADED_BEFORE_PUBLIC_INPUTS";
end
